<?php $c = App\Models\Customer::find(1); $vs = \App\Models\Voucher::where("type", "Sales")->where("status", "Posted")->whereHasMorph("reference", [\App\Models\Invoice::class], function($q) { $q->whereHas("sale", function($q2) { $q2->where("customer_id", 1); }); })->get(); foreach($vs as $v) { $inv = $v->reference; if(!$inv) { echo "No inv\n"; continue; } foreach($inv->items as $it) { $si = \App\Models\SaleItem::where("sale_id", $inv->sale_id)->where("product_id", $it->product_id)->first(); if(!$si) { echo "No si for prod ".$it->product_id."\n"; continue; } echo "inv qty: ".$si->invoiced_qty." ret qty: ".$si->returned_qty."\n"; } }
